                'name'        => 'Brightening Toner',
                'title'       => 'Alcohol-Free Brightening Facial Toner',
                'description' => '<p>Refresh and prep your skin with this alcohol-free brightening toner, infused with niacinamide and citrus extracts. It sweeps away leftover residue, tightens the look of pores, and leaves skin instantly refreshed and glowing. The gentle formula hydrates as it tones, making it a perfect daily step for all skin types.</p><p><strong>Key Features:</strong></p><ul><li>Niacinamide and citrus extracts</li><li>Alcohol free, pH balanced</li><li>Minimizes the look of pores</li><li>Instant refresh and hydration</li><li>Dermatologist tested</li><li>200 ml bottle</li></ul><p>Apply with a cotton pad after cleansing, morning and night, then follow with serum and moisturizer. The niacinamide works to even out skin tone while the citrus extracts refresh and tighten the look of pores, and the alcohol-free formula never stings or dries. A bright, even-toned base for the rest of your routine, it leaves skin feeling clean, calm, and ready. A gentle daily step for all skin types. The generous bottle lasts for months with daily use, making it a budget-friendly addition to your routine.</p>',
                'price'       => 1499.00,
                'main_image'  => 'https://images.unsplash.com/photo-1580870069867-74c57ee1bb07?w=600&q=80&auto=format',
                'seller_id'   => 13,
                'category_id' => 5,
            ],
        ];

        // Give roughly half the seeded products a sale (discounted) price so the
        // sale display can be previewed. A rotating set of multipliers keeps the
        // discount varied (10%–30% off). Products with an explicit
        // discounted_price key are left untouched.
        $discountMultipliers = [0.85, 0.75, 0.8, 0.9, 0.7];

        foreach ($products as $index => $product) {
            if (! isset($product['discounted_price']) && ($index % 2) === 1) {
                $multiplier = $discountMultipliers[$index % count($discountMultipliers)];
                $product['discounted_price'] = round($product['price'] * $multiplier, 2);
            }

            // Normalize the gallery to a plain array — the model casts 'images'
            // to array, so passing a pre-encoded JSON string would double-encode
            // it and make count($product->images) fail on the frontend.
            $images = is_array($product['images'] ?? null)
                ? $product['images']
                : (json_decode($product['images'] ?? '[]', true) ?: []);

            // Every seeded product must expose at least two gallery images.
            while (count($images) < 2) {
                $images[] = $product['main_image'];
            }

            $product['images'] = $images;

            // Stagger created_at so only some products appear "new" (within the
            // last 7 days) — otherwise every freshly seeded product shows the
            // New badge.
            $createdDaysAgo = [0, 3, 10, 1, 20, 5, 30, 2];
            $product['created_at'] = now()->subDays($createdDaysAgo[$index % count($createdDaysAgo)]);
            $product['updated_at'] = $product['created_at'];

            Product::create($product);
        }
    }
}
